const $=s=>document.querySelector(s);
const suits=[{name:'HEARTS',symbol:'♥',red:true,freq:'pulse'},{name:'DIAMONDS',symbol:'♦',red:true,freq:'echo'},{name:'CLUBS',symbol:'♣',red:false,freq:'rift'},{name:'SPADES',symbol:'♠',red:false,freq:'void'}];
const rankNames={11:'J',12:'Q',13:'K',14:'A'};
const cycles=['THE FIRST LOOP','STATIC BLOOM','HOURGLASS SEA','THE LONG PAUSE','BROKEN ORBIT','GHOST FREQUENCY','LAST LIGHT','THE ENDLESS NOW'];
const targets=[300,800,2000,1800,4200,9000,7000,15000,32000,18000,45000,100000,65000,140000,300000,160000,350000,750000,300000,650000,1500000,500000,2000000,10000000];
const encounters=[['THE ECHO','A faint repetition from another timeline.','⌁'],['THE KNOT','Two moments, pulled into one.','∞'],['THE FIRST ANOMALY','The loop closes. Something watches.','◉'],['THE DRIFT','A memory without an owner.','⌁'],['THE GLASS HOUR','Every reflection arrives too soon.','◇'],['THE MIRROR ENGINE','It remembers the future you forgot.','◉']];
const relicPool=[
 {name:'Stopped Watch',icon:'◷',desc:'+1 temporal charge on every hand.',cost:8,key:'charge',value:1},
 {name:'Red Thread',icon:'⌁',desc:'All scored hands gain 20% power.',cost:10,key:'power',value:.2},
 {name:'The Fuse',icon:'ϟ',desc:'Every hand begins with +8 energy.',cost:9,key:'energy',value:8},
 {name:'Pocket Universe',icon:'✦',desc:'Matching frequencies add extra charge.',cost:11,key:'frequency',value:.5},
 {name:'Hourglass Shard',icon:'⌛',desc:'Gain one extra play each encounter.',cost:13,key:'plays',value:1},
 {name:'Lucky Coin',icon:'◈',desc:'Earn 3 extra Chronons after each anomaly.',cost:10,key:'coins',value:3}
];
const handInfo={high:['HIGH CARD',0,2],pair:['ONE PAIR',8,3.8],two:['TWO PAIR',14,5.2],three:['THREE OF A KIND',20,6.8],straight:['STRAIGHT',20,8],flush:['FLUSH',22,8.5],full:['FULL HOUSE',26,10],four:['FOUR OF A KIND',30,13],sf:['STRAIGHT FLUSH',35,18]};
let state;
function makeDeck(){return suits.flatMap((s,si)=>Array.from({length:13},(_,i)=>({id:`${si}-${i+2}`,rank:i+2,suit:si,freq:s.freq,mod:null})));}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function init(){state={cycle:0,stage:0,score:0,chronons:12,plays:4,discards:3,deck:shuffle(makeDeck()),discard:[],hand:[],selected:[],relics:[{...relicPool[0]}],won:false,over:false,muted:false};drawToEight();startEncounter(false);render();}
function drawToEight(){while(state.hand.length<8){if(!state.deck.length){if(!state.discard.length)break;state.deck=shuffle(state.discard);state.discard=[];}state.hand.push(state.deck.pop());}}
function index(){return state.cycle*3+state.stage}
function encounter(){return encounters[(state.cycle*3+state.stage)%encounters.length]}
function isBoss(){return state.stage===2}
function target(){return targets[index()]||10000000}
function special(){if(!isBoss())return null;return state.cycle%3===0?'The hour repeats':'The fracture widens'}
function startEncounter(addLog=true){state.score=0;state.plays=4+(has('plays')?1:0);state.discards=3;state.selected=[];state.won=false;state.over=false;if(addLog)log(`Cycle ${String(state.cycle+1).padStart(2,'0')} — ${encounter()[0]} detected.`);render();}
function has(k){return state.relics.some(r=>r.key===k)}
function amount(k){return state.relics.filter(r=>r.key===k).reduce((a,r)=>a+r.value,0)}
function analyze(cards){if(!cards.length)return{type:'high',energy:0,charge:0,label:'NO CARDS'};let vals=cards.map(c=>c.rank).sort((a,b)=>a-b);let counts={};vals.forEach(v=>counts[v]=(counts[v]||0)+1);let groups=Object.values(counts).sort((a,b)=>b-a);let flush=cards.length===5&&cards.every(c=>c.suit===cards[0].suit);let straight=cards.length===5&&((new Set(vals).size===5&&(vals[4]-vals[0]===4))||(vals.join(',')==='2,3,4,5,14'));let type='high';if(straight&&flush)type='sf';else if(groups[0]===4)type='four';else if(groups[0]===3&&groups[1]===2)type='full';else if(flush)type='flush';else if(straight)type='straight';else if(groups[0]===3)type='three';else if(groups[0]===2&&groups[1]===2)type='two';else if(groups[0]===2)type='pair';let [label,bonus,mult]=handInfo[type];let energy=vals.reduce((a,v)=>a+Math.min(v,10)+(v>10?10:0),0)+bonus;let fcounts={};cards.forEach(c=>fcounts[c.freq]=(fcounts[c.freq]||0)+1);let matching=Math.max(...Object.values(fcounts));let charge=mult+(matching-1)*.18+amount('charge')+(has('frequency')?(matching-1)*.5:0);if(state.cycle>0&&state.stage===2&&state.cycle%4===3)charge*=1.08;let power=1+amount('power');let total=Math.floor((energy+amount('energy'))*charge*power);return{type,energy:energy+amount('energy'),charge,label,total,matching};}
function preview(){return analyze(state.selected)}
function toggleCard(id){if(state.won||state.over)return;let i=state.selected.indexOf(id);if(i>=0)state.selected.splice(i,1);else if(state.selected.length<5)state.selected.push(id);else toast('A hand can contain up to five cards.');render();}
function play(){if(!state.selected.length){toast('Select at least one card to play.');return}if(state.plays<=0||state.won||state.over)return;let cards=state.selected.map(id=>state.hand.find(c=>c.id===id)).filter(Boolean);let a=analyze(cards);state.score+=a.total;state.plays--;state.hand=state.hand.filter(c=>!state.selected.includes(c.id));state.discard.push(...cards);state.selected=[];drawToEight();$('#lastScore').textContent=a.total.toLocaleString();$('#lastHand').textContent=a.label;log(`${a.label} — ${a.energy} energy × ${a.charge.toFixed(1)} charge = ${a.total.toLocaleString()}.`);if(state.score>=target()){winEncounter()}else if(state.plays<=0){state.over=true;log('The anomaly overwhelms the timeline.');openGameOver()}render();}
function discardSelected(){if(!state.selected.length){toast('Select cards to discard.');return}if(!state.discards||state.won||state.over)return;let cards=state.selected.map(id=>state.hand.find(c=>c.id===id)).filter(Boolean);state.hand=state.hand.filter(c=>!state.selected.includes(c.id));state.discard.push(...cards);state.selected=[];state.discards--;drawToEight();log(`Discarded ${cards.length} card${cards.length===1?'':'s'} to reshape fate.`);render();}
function winEncounter(){state.won=true;state.chronons+=6+amount('coins');log(`${encounter()[0]} stabilized. +${6+amount('coins')} Chronons.`);render();setTimeout(()=>openVictory(),250)}
function advance(){if(state.stage<2){state.stage++;startEncounter();return}if(state.cycle<7){state.cycle++;state.stage=0;startEncounter();return}state.over=true;openEnding();}
function openVictory(){let boss=isBoss();let content=`<h2 class="success">ANOMALY STABILIZED</h2><p class="sub">CYCLE ${String(state.cycle+1).padStart(2,'0')} &nbsp; / &nbsp; ${encounter()[0]}</p><p>You bent the loop without breaking it. Your score of <b>${state.score.toLocaleString()}</b> exceeds the threshold of ${target().toLocaleString()}.</p><p>Recovered <b class="success">${6+amount('coins')} Chronons</b>. ${boss?'The fracture leaves a moment to breathe — the black market is open.':'A new signal is already forming.'}</p><div class="modal-actions"><button class="btn btn-play" id="victoryContinue">${boss?'ENTER THE BLACK MARKET':'NEXT ANOMALY'} <span>↗</span></button></div>`;openModal(content);$('#victoryContinue').onclick=()=>boss?openShop():closeModalAndAdvance();}
function closeModalAndAdvance(){closeModal();advance()}
function openShop(){let available=relicPool.filter(r=>!state.relics.some(owned=>owned.name===r.name)).sort(()=>Math.random()-.5).slice(0,3);if(!available.length)available=[{name:'Chronon Cache',icon:'◈',desc:'Recover 5 Chronons for your journey.',cost:0,key:'cash',value:5}];let items=available.map((r,i)=>`<article class="shop-item"><div class="shop-icon">${r.icon}</div><b>${r.name}</b><p>${r.desc}</p><button data-buy="${i}" ${state.chronons<r.cost?'disabled':''}>${r.cost?`${r.cost} CHRONONS`:'CLAIM FREE'}</button></article>`).join('');openModal(`<h2>THE BLACK MARKET</h2><p class="sub">AN UNTIME PLACE &nbsp; / &nbsp; ${state.chronons} CHRONONS</p><p>Trade what you have for something that might outlast the loop.</p><div class="shop-grid">${items}</div><div class="modal-actions"><button class="btn btn-play" id="shopContinue">LEAVE MARKET <span>↗</span></button></div>`);document.querySelectorAll('[data-buy]').forEach(btn=>btn.onclick=()=>{let r=available[+btn.dataset.buy];if(r.key==='cash'){state.chronons+=r.value}else if(state.chronons>=r.cost){state.chronons-=r.cost;state.relics.push(r)}else return;log(`${r.name} added to your collection.`);openShop();render()});$('#shopContinue').onclick=closeModalAndAdvance;}
function openGameOver(){openModal(`<h2>THE LOOP COLLAPSES</h2><p class="sub">RUN TERMINATED &nbsp; / &nbsp; CYCLE ${String(state.cycle+1).padStart(2,'0')}</p><p>The anomaly held. You scored <b>${state.score.toLocaleString()}</b> of the required ${target().toLocaleString()}.</p><p>Time is patient. It will let you try again.</p><div class="modal-actions"><button class="btn btn-play" id="retry">RESTART RUN <span>↗</span></button></div>`);$('#retry').onclick=()=>{closeModal();init()}}
function openEnding(){openModal(`<h2 class="success">THE LOOP IS YOURS</h2><p class="sub">CYCLE 08 &nbsp; / &nbsp; ANOMALY RESOLVED</p><p>Ten million points. Eight cycles. One impossible hand. You didn't escape time — you learned how to play it.</p><p class="success">CHRONO-HAND COMPLETE</p><div class="modal-actions"><button class="btn btn-play" id="again">PLAY AGAIN <span>↗</span></button></div>`);$('#again').onclick=()=>{closeModal();init()}}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function help(){openModal(`<h2>HOW TO PLAY</h2><p class="sub">A POKER ROGUELIKE AGAINST TIME</p><p><b>1.</b> Select up to five cards from your hand. Combine poker hands for more Energy and Temporal Charge.</p><p><b>2.</b> Play hands to build your score past the anomaly threshold. You have four plays and three discards each encounter.</p><p><b>3.</b> A hand scores <b>Energy × Temporal Charge</b>. Better poker combinations multiply harder; matching frequencies add charge.</p><p><b>4.</b> Stabilize three anomalies per cycle. Collect Chronons, buy relics after each boss, and survive all eight cycles.</p><p>Tip: discard low-value cards to hunt pairs and five-card combinations. Relics stack.</p><div class="modal-actions"><button class="btn btn-play" id="gotIt">UNDERSTOOD</button></div>`);$('#gotIt').onclick=closeModal;}
function openDeck(){let all=[...state.hand,...state.deck,...state.discard].sort((a,b)=>a.suit-b.suit||a.rank-b.rank);let tally={};all.forEach(c=>tally[c.freq]=(tally[c.freq]||0)+1);openModal(`<h2>THE DECK</h2><p class="sub">${all.length} CARDS REMAIN IN THIS TIMELINE</p><p>${Object.entries(tally).map(([k,v])=>`<b style="color:var(--${k==='pulse'?'amber':k})">${k.toUpperCase()}</b> ${v}`).join(' &nbsp; / &nbsp; ')}</p><p>52 cards across four frequencies. Hearts carry Pulse, Diamonds Echo, Clubs Rift, and Spades Void. The deck reshuffles when the draw pile runs dry.</p><div class="modal-actions"><button class="btn btn-play" id="deckClose">CLOSE</button></div>`);$('#deckClose').onclick=closeModal}
function log(text){let el=$('#log');let p=document.createElement('p');p.innerHTML=`<i>04:${String(30+el.children.length).padStart(2,'0')}</i> ${text}`;el.prepend(p);while(el.children.length>8)el.lastElementChild.remove()}
let toastTimer;function toast(text){let t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
