class="center-suit">${s.symbol}</div><div class="freq-tag freq-${c.freq}">${c.freq.toUpperCase()}</div></div>`}).join('');$('#cards').querySelectorAll('.playing-card').forEach(el=>{el.onclick=()=>toggleCard(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleCard(el.dataset.id)}}});$('#relics').innerHTML=state.relics.map(r=>`<div class="relic" title="${r.name}: ${r.desc}">${r.icon}<small>+</small></div>`).join('');$('#timeline').innerHTML=Array.from({length:8},(_,i)=>`<div class="timeline-item ${i<state.cycle?'done':i===state.cycle?'current':''}"><b>CYCLE ${String(i+1).padStart(2,'0')}</b><small>${cycles[i].replace('THE ','')}</small></div>`).join('');let sp=special();$('#ruleTitle').textContent=sp||(state.stage===1?'A split second':'Time is a flat circle');$('#ruleText').textContent=sp==='The hour repeats'?'The boss steals one discard from your supply.':sp==='The fracture widens'?'Final boss hands receive a charge bonus.':state.stage===1?'Each matching frequency adds to your charge.':'No temporal interference detected.';$('#bossIcon').innerHTML=`<span>${encounter()[2]}</span>`;}
