 function special(){if(!isBoss())return null;return state.cycle%3===0?'The hour repeats':'The fracture widens'}
 function startEncounter(addLog=true){state.score=0;state.plays=4+(has('plays')?1:0);state.discards=isBoss()&&state.cycle%3===0?2:3;state.selected=[];state.won=false;state.over=false;if(addLog)log(`Cycle ${String(state.cycle+1).padStart(2,'0')} — ${encounter()[0]} detected.`);render();}
 function has(k){return state.relics.some(r=>r.key===k)}
 function amount(k){return state.relics.filter(r=>r.key===k).reduce((a,r)=>a+r.value,0)}
